function splitScopeIds(value) {
  return (value || "")
    .split(",")
    .map((id) => id.trim())
    .filter(Boolean)
}

function commandQueueScopeConfig() {
  const url = new URL(dashboardUrl())
  const missionId = expectedMissionId()
  const sourceEndpointId = expectedSourceEndpointId()
  const urlScopeKind = url.searchParams.get("scope_kind") || "mission"
  const urlScopeId = url.searchParams.get("scope_id") || ""
  const urlScopeIds = splitScopeIds(url.searchParams.get("scope_ids"))

  if (urlScopeKind === "source_endpoint") {
    const scopeIds = urlScopeIds.length > 0 ? urlScopeIds : [sourceEndpointId || urlScopeId].filter(Boolean)
    const scopeIdsParam = scopeIds.join(",")
    const resourceId = scopeIds.length > 1 ? scopeIdsParam : scopeIds[0]

    return {
      missionId,
      sourceEndpointId,
      resourceScopeKind: "source_endpoint",
      resourceId,
      rootScopeId: scopeIds[0] || "",
      routeScopeId: scopeIds.length > 1 ? "" : resourceId,
      expectedScopeIds: scopeIds,
      expectedScopeIdsParam: scopeIdsParam,
      expectedEvidenceScopeIds: scopeIds.length > 1 ? scopeIdsParam : "",
      resourceLinkExpected: scopeIds.length === 1,
    }
  }

  if (urlScopeKind === "spacecraft") {
    const scopeIds = urlScopeIds.length > 0 ? urlScopeIds : [urlScopeId].filter(Boolean)
    const scopeIdsParam = scopeIds.join(",")
    const resourceId = scopeIds.length > 1 ? scopeIdsParam : scopeIds[0]

    return {
      missionId,
      sourceEndpointId,
      resourceScopeKind: "spacecraft",
      resourceId,
      rootScopeId: scopeIds[0] || "",
      routeScopeId: scopeIds.length > 1 ? "" : resourceId,
      expectedScopeIds: scopeIds,
      expectedScopeIdsParam: scopeIdsParam,
      expectedEvidenceScopeIds: scopeIds.length > 1 ? scopeIdsParam : "",
      resourceLinkExpected: false,
    }
  }

  return {
    missionId,
    sourceEndpointId,
    resourceScopeKind: "mission",
    resourceId: missionId,
    rootScopeId: missionId,
    routeScopeId: missionId,
    expectedScopeIds: [missionId],
    expectedScopeIdsParam: missionId,
    expectedEvidenceScopeIds: "",
    resourceLinkExpected: false,
  }
}

