async function evaluateViewport(client, viewport, profile) {
  const criticalSelector = JSON.stringify(profile.criticalSelector)
  const gridItemSelector = JSON.stringify(profile.gridItemSelector)
  const chartSelector = JSON.stringify(profile.chartSelector)
  const panelSelector = JSON.stringify(profile.panelSelector)
  const copySelector = JSON.stringify(profile.copySelector)
  const copyClickSelector = JSON.stringify(profile.copyClickSelector)
  const allowedOverlapSelector = JSON.stringify(profile.allowedOverlapSelector)
  const textSelector = JSON.stringify(profile.textSelector)
  const checkVerticalTextOverflow = JSON.stringify(profile.checkVerticalTextOverflow)
  const requireLiveSocket = JSON.stringify(profile.requireLiveSocket)
  const requireDashboardGridHook = JSON.stringify(profile.requireDashboardGridHook)
  const requireCopyClick = JSON.stringify(profile.requireCopyClick)
  const requireSelectedDataLinkCopyPayload = JSON.stringify(profile.requireSelectedDataLinkCopyPayload)

  const expression = `
    (async () => {
      const criticalSelector = ${criticalSelector}
      const gridItemSelector = ${gridItemSelector}
      const chartSelector = ${chartSelector}
      const panelSelector = ${panelSelector}
      const copySelector = ${copySelector}
      const copyClickSelector = ${copyClickSelector}
      const allowedOverlapSelector = ${allowedOverlapSelector}
      const textSelector = ${textSelector}
      const checkVerticalTextOverflow = ${checkVerticalTextOverflow}
      const requireLiveSocket = ${requireLiveSocket}
      const requireDashboardGridHook = ${requireDashboardGridHook}
      const requireCopyClick = ${requireCopyClick}
      const requireSelectedDataLinkCopyPayload = ${requireSelectedDataLinkCopyPayload}

      const box = (el) => {
        const rect = el.getBoundingClientRect()
        return {
          id: el.id || el.getAttribute("gs-id") || el.getAttribute("data-viewport-critical") || el.tagName,
          x: rect.x,
          y: rect.y,
          width: rect.width,
          height: rect.height,
          right: rect.right,
          bottom: rect.bottom
        }
      }

      const visible = (el) => {
        const rect = el.getBoundingClientRect()
        const style = getComputedStyle(el)
        return rect.width > 0 && rect.height > 0 && style.visibility !== "hidden" && style.display !== "none"
      }

      const allowsOverlap = (el) => {
        return allowedOverlapSelector && el.closest(allowedOverlapSelector)
      }

      const copyButton = copyClickSelector && document.querySelector(copyClickSelector)
      if (copyButton) {
        copyButton.click()
        await new Promise((resolve) => setTimeout(resolve, 50))
      }

      const clipboardPayload = (selector) => {
        const el = document.querySelector(selector)
        return {
          present: Boolean(el),
          hook: el?.getAttribute("phx-hook") || "",
          raw: el?.dataset.clipboardText || "",
          copied: el?.dataset.clipboardCopied || ""
        }
      }

      const critical = Array.from(document.querySelectorAll(criticalSelector)).filter(visible)
      const criticalBoxes = critical.map(box)
      const overlapping = []

      for (let i = 0; i < criticalBoxes.length; i += 1) {
        for (let j = i + 1; j < criticalBoxes.length; j += 1) {
          if (critical[i].contains(critical[j]) || critical[j].contains(critical[i])) {
            continue
          }

          if (allowsOverlap(critical[i]) || allowsOverlap(critical[j])) {
            continue
          }

          const a = criticalBoxes[i]
          const b = criticalBoxes[j]
          const xOverlap = Math.max(0, Math.min(a.right, b.right) - Math.max(a.x, b.x))
          const yOverlap = Math.max(0, Math.min(a.bottom, b.bottom) - Math.max(a.y, b.y))

          if (xOverlap > 1 && yOverlap > 1) {
            overlapping.push({ a: a.id, b: b.id, xOverlap, yOverlap })
          }
        }
      }

      const textOverflow = Array.from(document.querySelectorAll(textSelector))
        .filter(visible)
        .filter((el) => (
          el.scrollWidth > el.clientWidth + 1 ||
          (checkVerticalTextOverflow && el.scrollHeight > el.clientHeight + 1)
        ))
        .map((el) => ({
          id: el.id || el.getAttribute("data-viewport-critical") || el.textContent.trim().slice(0, 48),
          text: el.textContent.trim().slice(0, 80),
          clientWidth: el.clientWidth,
          scrollWidth: el.scrollWidth,
          clientHeight: el.clientHeight,
          scrollHeight: el.scrollHeight
        }))

      const offscreen = criticalBoxes.filter(
        (rect) => rect.x < -1 || rect.right > window.innerWidth + 1 || rect.y < -1
      )

      return {
        url: window.location.href,
        viewport: { width: window.innerWidth, height: window.innerHeight },
        documentWidth: document.documentElement.scrollWidth,
        bodyWidth: document.body.scrollWidth,
        horizontalOverflow: document.documentElement.scrollWidth > window.innerWidth + 1,
        criticalCount: criticalBoxes.length,
        gridItemCount: document.querySelectorAll(gridItemSelector).length,
        chartCount: document.querySelectorAll(chartSelector).length,
        panelCount: document.querySelectorAll(panelSelector).length,
        copyButtonCount: document.querySelectorAll(copySelector).length,
        zeroSize: criticalBoxes.filter((rect) => rect.width < 1 || rect.height < 1),
        offscreen,
        overlapping,
        textOverflow,
        liveSocketConnected: Boolean(window.liveSocket && window.liveSocket.isConnected && window.liveSocket.isConnected()),
        dashboardGridHookMounted: Boolean(
          document.querySelector("[phx-hook='DashboardGrid'].grid-stack[class*='gs-id-']")
        ),
        copyClickSucceeded: Boolean(copyButton && copyButton.dataset.clipboardCopied === "true"),
        dataLinkCopyPayload: clipboardPayload("#dashboard-data-link-copy-link"),
        evidenceCopyPayload: clipboardPayload("#dashboard-evidence-copy-link"),
        requireLiveSocket,
        requireDashboardGridHook,
        requireCopyClick,
        requireSelectedDataLinkCopyPayload
      }
    })()
  `

  const result = await client.send("Runtime.evaluate", {
    expression,
    returnByValue: true,
    awaitPromise: true,
  })

  if (result.exceptionDetails) {
    const details = result.exceptionDetails
    const description = details.exception?.description || details.text || "unknown browser error"
    throw new Error(`Viewport evaluation failed for ${viewport.name}: ${description}`)
  }

  return { name: viewport.name, ...result.result.value }
}

function assertViewport(result) {
  assert.equal(result.horizontalOverflow, false, `${result.name} has horizontal overflow`)
  assert.equal(result.gridItemCount >= 3, true, `${result.name} should render dashboard grid items`)
  assert.equal(result.chartCount >= 1, true, `${result.name} should render a chart surface`)
  assert.equal(result.panelCount >= 1, true, `${result.name} should render an inspector panel`)
  assert.equal(result.copyButtonCount >= 1, true, `${result.name} should render a copy action`)
  assert.deepEqual(result.zeroSize, [], `${result.name} has zero-sized critical regions`)
  assert.deepEqual(result.offscreen, [], `${result.name} has offscreen critical regions`)
  assert.deepEqual(result.overlapping, [], `${result.name} has overlapping critical regions`)
  assert.deepEqual(result.textOverflow, [], `${result.name} has text overflow`)

  if (result.requireLiveSocket) {
    assert.equal(result.liveSocketConnected, true, `${result.name} should have a connected LiveSocket`)
  }

  if (result.requireDashboardGridHook) {
    assert.equal(result.dashboardGridHookMounted, true, `${result.name} should mount DashboardGrid`)
  }

  if (result.requireCopyClick) {
    assert.equal(result.copyClickSucceeded, true, `${result.name} should run ClipboardButton on click`)
  }

  if (result.requireSelectedDataLinkCopyPayload) {
    assert.equal(result.dataLinkCopyPayload.present, true, `${result.name} should render selected data-link copy control`)
    assert.equal(
      result.dataLinkCopyPayload.hook,
      "ClipboardButton",
      `${result.name} data-link copy should use ClipboardButton`
    )
    assert.match(
      result.dataLinkCopyPayload.raw,
      /[?&]panel=data_link(?:&|$)/,
      `${result.name} data-link copy should preserve selected panel`
    )
    assert.match(
      result.dataLinkCopyPayload.raw,
      /[?&]selected_target=telemetry_sample(?:&|$)/,
      `${result.name} data-link copy should preserve selected target`
    )
    assert.match(
      result.dataLinkCopyPayload.raw,
      /[?&]selected_id=[^&]+/,
      `${result.name} data-link copy should preserve selected id`
    )
    assert.match(
      result.dataLinkCopyPayload.raw,
      /[?&]selected_placement=[^&]+/,
      `${result.name} data-link copy should preserve selected placement`
    )
  }
}

async function inspectRenderedLimitAnalysisEvidence(client, options = {}) {
  await waitForExpression(
    client,
    `
      Boolean(
        document.querySelector(
          "[data-limit-marker-target='limit analysis bucket'][data-limit-selected-clock]:not([data-limit-selected-clock=''])"
        )
      )
    `,
    5_000,
    "rendered limit analysis bucket selected-clock evidence"
  )

  const result = await client.send("Runtime.evaluate", {
    expression: `
      (() => {
        const parseMetadata = (value) => {
          if (!value) return null
          try {
            return JSON.parse(value)
          } catch (_error) {
            return value
          }
        }

        const markers = Array.from(
          document.querySelectorAll("[data-limit-marker-target='limit analysis bucket']")
        ).map((marker) => ({
          id: marker.dataset.limitMarkerId || "",
          ref: marker.dataset.limitMarkerRef || "",
          state: marker.dataset.limitBucketState || "",
          eventCount: marker.dataset.limitBucketEventCount || "",
          divergenceCount: marker.dataset.limitBucketDivergenceCount || "",
          definitionId: marker.dataset.limitDefinitionId || "",
          definitionVersion: marker.dataset.limitDefinitionVersion || "",
          limitSetName: marker.dataset.limitSetName || "",
          selectedClock: parseMetadata(marker.dataset.limitSelectedClock || ""),
          selectedDefinitionIntervals: parseMetadata(marker.dataset.limitSelectedDefinitionIntervals || "")
        }))
        const root = document.querySelector("#ops-dashboard-show-page")

        return {
          count: markers.length,
          markers,
          sourceDependencies: root?.dataset.engineSourceDependencies || "",
          sourceDependencyCount: root?.dataset.engineSourceDependencyCount || ""
        }
      })()
    `,
    returnByValue: true,
  })

  const snapshot = result.result.value
  assert.equal(snapshot.count >= 1, true, "dashboard should render limit analysis bucket markers")

  const marker = snapshot.markers.find((candidate) => candidate.selectedClock)
  assert.ok(marker, "limit analysis bucket should expose selected-clock metadata")
  assert.equal(
    marker.selectedClock.observed,
    "limit_event_receipt_time",
    "limit analysis bucket should explain the observed limit clock"
  )
  assert.notEqual(
    marker.selectedClock.requested_time_mode || "",
    "",
    "limit analysis bucket selected-clock metadata should preserve requested time mode"
  )
  if (options.expectedTimeMode) {
    assert.equal(
      marker.selectedClock.requested_time_mode,
      options.expectedTimeMode,
      `limit analysis bucket selected-clock metadata should preserve ${options.expectedTimeMode} time mode`
    )
  }
  if (options.expectedSourceDependency) {
    assert.match(
      snapshot.sourceDependencies,
      new RegExp(options.expectedSourceDependency),
      `dashboard root should expose source dependency ${options.expectedSourceDependency}`
    )
    assert.notEqual(
      snapshot.sourceDependencyCount,
      "",
      "dashboard root should expose a source dependency count"
    )
  }
  assert.notEqual(
    marker.selectedClock.requested_time_axis || "",
    "",
    "limit analysis bucket selected-clock metadata should preserve requested time axis"
  )
  assert.equal(
    Array.isArray(marker.selectedDefinitionIntervals),
    true,
    "limit analysis bucket should expose selected definition intervals as structured metadata"
  )
  assert.equal(
    marker.selectedDefinitionIntervals.length >= 1,
    true,
    "limit analysis bucket should include at least one selected definition interval"
  )
  assert.notEqual(
    marker.selectedDefinitionIntervals[0].limit_definition_id || marker.definitionId,
    "",
    "limit analysis bucket selected interval should identify the limit definition"
  )

  let frameEvidence = null

  if (options.inspectFrameEvidence) {
    await clickAndWaitForSelector(
      client,
      "[data-widget-frame-evidence]",
      "#dashboard-evidence-inspector[data-evidence-kind='frame'][data-evidence-status='resolved']",
      "dashboard frame evidence with limit overlay intervals"
    )

    const evidenceResult = await client.send("Runtime.evaluate", {
      expression: `
        (() => {
          const inspector = document.querySelector("#dashboard-evidence-inspector")
          const copy = document.querySelector("#dashboard-evidence-copy-link")
          const detailText = (label) => (
            Array.from(inspector?.querySelectorAll("[data-evidence-detail]") || [])
              .find((field) => field.dataset.evidenceDetail === label)
              ?.textContent?.replace(/\\s+/g, " ").trim() || ""
          )

          return {
            present: Boolean(inspector),
            kind: inspector?.dataset.evidenceKind || "",
            status: inspector?.dataset.evidenceStatus || "",
            subject: inspector?.dataset.evidenceSubject || "",
            limitDefinitionInterval: detailText("Limit definition interval"),
            limitDefinitionLifecycleEvent: detailText("Limit definition interval lifecycle event"),
            catalogRevisionInterval: detailText("Catalog revision interval"),
            catalogRevisionSourceEvent: detailText("Catalog revision interval source event"),
            copyText: copy?.dataset.clipboardText || ""
          }
        })()
      `,
      returnByValue: true,
    })

    frameEvidence = evidenceResult.result.value
    assert.equal(frameEvidence.present, true, "frame evidence inspector should render")
    assert.equal(frameEvidence.kind, "frame", "frame evidence inspector should preserve frame kind")
    assert.equal(frameEvidence.status, "resolved", "frame evidence inspector should resolve")
    assert.match(
      frameEvidence.subject,
      /HK\.counter/,
      "frame evidence inspector should identify the selected counter frame"
    )
    assert.match(
      frameEvidence.limitDefinitionInterval,
      new RegExp(expectedLimitDefinitionId()),
      "frame evidence should expose the selected limit definition interval"
    )
    assert.match(
      frameEvidence.limitDefinitionInterval,
      new RegExp(expectedLimitSetName()),
      "frame evidence should expose the selected limit set name"
    )
    assert.notEqual(
      frameEvidence.limitDefinitionLifecycleEvent,
      "",
      "frame evidence should expose the selected limit-definition lifecycle event"
    )

    const catalogRevisionId = expectedCatalogRevisionId()
    if (catalogRevisionId) {
      assert.match(
        frameEvidence.catalogRevisionInterval,
        new RegExp(catalogRevisionId),
        "frame evidence should expose the selected catalog revision interval"
      )
      assert.notEqual(
        frameEvidence.catalogRevisionSourceEvent,
        "",
        "frame evidence should expose the selected catalog revision source event"
      )
    }
    assert.match(
      frameEvidence.copyText,
      /selected_evidence_kind=frame/,
      "frame evidence copy payload should preserve frame evidence selection"
    )
  }

  return {...snapshot, frameEvidence}
}

async function inspectRenderedSourceDependencyCause(client, options = {}) {
  await clickAndWaitForSelector(
    client,
    "#dashboard-diagnostics-button",
    "#dashboard-source-dependency-causes [data-source-dependency-cause]",
    "source dependency causes"
  )

  const dependencyResult = await client.send("Runtime.evaluate", {
    expression: `
      (() => {
        const panel = document.querySelector("#dashboard-diagnostics-panel")
        const root = document.querySelector("#dashboard-source-dependency-causes")
        const row = root?.querySelector("[data-source-dependency-cause]")

        return {
          panelPresent: Boolean(panel),
          rootPresent: Boolean(root),
          count: root?.dataset.sourceDependencyCauseCount || "",
          dependencyEvidence: panel?.dataset.runtimeSourceDependencyEvidence || "",
          dependencyDegradedCount: panel?.dataset.runtimeSourceDependencyDegradedCount || "",
          requestId: row?.dataset.sourceDependencyCause || "",
          requestSource: row?.dataset.sourceDependencyRequestSource || "",
          upstreamSource: row?.dataset.sourceDependencyUpstreamSource || "",
          upstreamRequest: row?.dataset.sourceDependencyUpstreamRequest || "",
          upstreamStatus: row?.dataset.sourceDependencyUpstreamStatus || "",
          upstreamRuntimeAction: row?.dataset.sourceDependencyUpstreamRuntimeAction || "",
          upstreamWatermarkState: row?.dataset.sourceDependencyUpstreamWatermarkState || "",
          evidenceMode: row?.getAttribute("phx-value-source-evidence-mode") || "",
          evidenceRequestId: row?.getAttribute("phx-value-source-request-id") || "",
          evidenceLogicalSource: row?.getAttribute("phx-value-logical-source") || "",
          text: row?.textContent?.replace(/\\s+/g, " ").trim() || ""
        }
      })()
    `,
    returnByValue: true,
  })

  const snapshot = dependencyResult.result.value
  assert.equal(snapshot.panelPresent, true, "diagnostics panel should render for dependency cause inspection")
  assert.equal(snapshot.rootPresent, true, "diagnostics should render source dependency causes")
  assert.notEqual(snapshot.count, "", "source dependency cause section should expose count")
  assert.notEqual(snapshot.requestId, "", "source dependency cause should expose dependent request id")
  assert.equal(
    snapshot.requestSource,
    options.expectedRequestSource || "limits",
    "source dependency cause should identify the dependent logical source"
  )
  assert.equal(
    snapshot.upstreamSource,
    options.expectedUpstreamSource || "telemetry",
    "source dependency cause should identify the upstream logical source"
  )
  assert.notEqual(snapshot.upstreamRequest, "", "source dependency cause should expose upstream request id")
  assert.notEqual(snapshot.upstreamStatus, "", "source dependency cause should expose upstream status")
  assert.equal(
    snapshot.evidenceMode,
    "execution",
    "source dependency cause should open upstream source execution evidence"
  )
  assert.equal(
    snapshot.evidenceRequestId,
    snapshot.upstreamRequest,
    "source dependency cause evidence action should target the upstream request"
  )
  assert.equal(
    snapshot.evidenceLogicalSource,
    snapshot.upstreamSource,
    "source dependency cause evidence action should target the upstream logical source"
  )
  assert.match(
    snapshot.text,
    /Limits waiting on telemetry input/,
    "source dependency cause should explain the Limits telemetry dependency"
  )

  await clickAndWaitForSelector(
    client,
    "#dashboard-source-dependency-causes [data-source-dependency-cause]",
    "#dashboard-evidence-inspector[data-evidence-kind='source']",
    "upstream source dependency evidence"
  )

  const evidenceResult = await client.send("Runtime.evaluate", {
    expression: `
      (() => {
        const inspector = document.querySelector("#dashboard-evidence-inspector")
        const url = new URL(window.location.href)

        return {
          present: Boolean(inspector),
          kind: inspector?.dataset.evidenceKind || "",
          subject: inspector?.dataset.evidenceSubject || "",
          status: inspector?.dataset.evidenceStatus || "",
          selectedSourceEvidenceMode: url.searchParams.get("selected_source_evidence_mode") || "",
          selectedSourceRequest: url.searchParams.get("selected_source_request") || "",
          selectedLogicalSource: url.searchParams.get("selected_logical_source") || ""
        }
      })()
    `,
    returnByValue: true,
  })

  const evidence = evidenceResult.result.value
  assert.equal(evidence.present, true, "source dependency cause should open evidence inspector")
  assert.equal(evidence.kind, "source", "dependency cause evidence inspector should be source evidence")
  assert.equal(
    evidence.selectedSourceEvidenceMode,
    "execution",
    "dependency cause should preserve execution evidence mode in the route"
  )
  assert.equal(
    evidence.selectedSourceRequest,
    snapshot.upstreamRequest,
    "dependency cause should preserve upstream source request in the route"
  )
  assert.equal(
    evidence.selectedLogicalSource,
    snapshot.upstreamSource,
    "dependency cause should preserve upstream logical source in the route"
  )

  return { dependency: snapshot, evidence }
}

async function inspectOpsContextRail(client, options = {}) {
  const { expectInitiallyExpanded = false, restoreCollapsed = false } = options

  await waitForExpression(
    client,
    `
      Boolean(
        document.querySelector("#ops-context-rail[data-ops-context-rail]") &&
        document.querySelector("#ops-context-rail-toggle")
      )
    `,
    5_000,
    "dashboard ops context rail"
  )

  const snapshotResult = await client.send("Runtime.evaluate", {
    expression: `
      (() => {
        const rail = document.querySelector("#ops-context-rail")
        const sectionKeys = Array.from(document.querySelectorAll("[data-ops-context-section]"))
          .map((section) => section.dataset.opsContextSection)
        const collapsedKeys = Array.from(document.querySelectorAll("[data-ops-context-collapsed-section]"))
          .map((section) => section.dataset.opsContextCollapsedSection)

        return {
          present: Boolean(rail),
          expanded: rail?.hasAttribute("data-expanded") || false,
          width: rail ? Math.round(rail.getBoundingClientRect().width) : 0,
          storageKey: rail?.dataset.storageKey || "",
          defaultExpanded: rail?.hasAttribute("data-default-expanded") || false,
          sectionKeys,
          collapsedKeys,
          comparisonStatus: document
            .querySelector("[data-ops-context-section='comparison']")
            ?.dataset.opsContextSectionStatus || ""
        }
      })()
    `,
    returnByValue: true,
  })

  const snapshot = snapshotResult.result.value
  assert.equal(snapshot.present, true, "ops context rail should render")
  assert.equal(snapshot.storageKey, "cadence-ops-context-rail", "ops context rail should use the shared storage key")
  assert.equal(snapshot.defaultExpanded, false, "ops context rail should default collapsed")
  assert.equal(
    snapshot.expanded,
    expectInitiallyExpanded,
    "ops context rail should hydrate the expected expanded state"
  )
  assert.equal(
    snapshot.sectionKeys.every((key) => key === "comparison"),
    true,
    "dashboard context rail should only expose comparison sections"
  )
  assert.equal(snapshot.collapsedKeys.length >= snapshot.sectionKeys.length, true, "collapsed rail badges should mirror sections")

  if (!expectInitiallyExpanded) {
    await client.send("Runtime.evaluate", {
      expression: `
        (() => {
          document.querySelector("#ops-context-rail-toggle")?.click()
        })()
      `,
      returnByValue: true,
    })

    await waitForExpression(
      client,
      `
        Boolean(
          document.querySelector("#ops-context-rail")?.hasAttribute("data-expanded") &&
          JSON.parse(localStorage.getItem("cadence-ops-context-rail") || "{}").state === "expanded"
        )
      `,
      3_000,
      "ops context rail expansion persistence"
    )
  }

  const persistedResult = await client.send("Runtime.evaluate", {
    expression: `
      (() => {
        const rail = document.querySelector("#ops-context-rail")
        const stored = JSON.parse(localStorage.getItem("cadence-ops-context-rail") || "{}")

        return {
          expanded: rail?.hasAttribute("data-expanded") || false,
          width: rail ? Math.round(rail.getBoundingClientRect().width) : 0,
          storedState: stored.state || "",
          storedWidth: Number.isFinite(stored.width) ? stored.width : null
        }
      })()
    `,
    returnByValue: true,
  })

  const persisted = persistedResult.result.value

  if (expectInitiallyExpanded) {
    assert.equal(persisted.expanded, true, "ops context rail should remain expanded after reload")
    assert.equal(persisted.storedState, "expanded", "ops context rail should preserve expanded state in localStorage")
  }

  if (restoreCollapsed) {
    await client.send("Runtime.evaluate", {
      expression: `
        (() => {
          document.querySelector("#ops-context-rail-toggle")?.click()
        })()
      `,
      returnByValue: true,
    })

    await waitForExpression(
      client,
      `
        Boolean(
          !document.querySelector("#ops-context-rail")?.hasAttribute("data-expanded") &&
          JSON.parse(localStorage.getItem("cadence-ops-context-rail") || "{}").state === "collapsed"
        )
      `,
      3_000,
      "ops context rail collapse persistence"
    )
  }

  return { snapshot, persisted }
}

async function runLiveDashboardInteractions(client, url, profile) {
  if (!profile.requireLiveInteractions) return null

  await loadViewport(client, url, LIVE_INTERACTION_VIEWPORT)
  await waitForProfileReady(client, profile, LIVE_INTERACTION_VIEWPORT)

  const contextRail = await inspectOpsContextRail(client)

  const menuResult = await client.send("Runtime.evaluate", {
    expression: `
      (() => {
        const menu = document.querySelector("#dashboard-menu")
        const trigger = menu?.querySelector(":scope > [data-overlay-trigger]")
        const panel = menu?.querySelector(":scope > [data-overlay-panel]")
        trigger?.click()

        return {
          open: menu?.hasAttribute("data-overlay-open") && !panel?.hidden,
          expanded: trigger?.getAttribute("aria-expanded"),
          itemCount: panel?.querySelectorAll("[role='menuitem'], a, button").length || 0
        }
      })()
    `,
    returnByValue: true,
  })

  assert.equal(menuResult.result.value.open, true, "dashboard action menu should open")
  assert.equal(menuResult.result.value.expanded, "true", "dashboard action menu trigger should expand")
  assert.equal(menuResult.result.value.itemCount >= 3, true, "dashboard action menu should expose actions")

  await client.send("Input.dispatchKeyEvent", {
    type: "keyDown",
    key: "Escape",
    windowsVirtualKeyCode: 27,
    nativeVirtualKeyCode: 27,
  })
  await waitForExpression(
    client,
    `
      Boolean(
        !document.querySelector("#dashboard-menu")?.hasAttribute("data-overlay-open") &&
        document.querySelector("#dashboard-menu-menu")?.hidden
      )
    `,
    2_000,
    "dashboard action menu to close"
  )

  const contextResult = await client.send("Runtime.evaluate", {
    expression: `
      (() => {
        const visible = (el) => {
          if (!el) return false
          const rect = el.getBoundingClientRect()
          const style = getComputedStyle(el)
          return rect.width > 0 && rect.height > 0 && style.visibility !== "hidden" && style.display !== "none"
        }
        const dataControls = document.querySelector("#dashboard-data-controls")
        dataControls?.querySelector(":scope > [data-overlay-trigger]")?.click()

        return {
          overlayOpen: dataControls?.hasAttribute("data-overlay-open") || false,
          controlsVisible: visible(document.querySelector("#runtime-context-controls")),
          formPresent: Boolean(document.querySelector("#runtime-context-form")),
          sourceBindingPresent: Boolean(document.querySelector("#dashboard-source-binding")),
          timePresetCount: document.querySelectorAll("#dashboard-time-presets button").length
        }
      })()
    `,
    returnByValue: true,
  })

  assert.equal(contextResult.result.value.overlayOpen, true, "runtime context controls overlay should open")
  assert.equal(contextResult.result.value.controlsVisible, true, "runtime context controls should be visible in the open overlay")
  assert.equal(contextResult.result.value.formPresent, true, "runtime context form should render")
  assert.equal(contextResult.result.value.sourceBindingPresent, true, "source binding control should render")
  assert.equal(contextResult.result.value.timePresetCount >= 4, true, "time preset controls should render")

  await client.send("Input.dispatchKeyEvent", {
    type: "keyDown",
    key: "Escape",
    windowsVirtualKeyCode: 27,
    nativeVirtualKeyCode: 27,
  })
  await waitForExpression(
    client,
    `
      Boolean(
        !document.querySelector("#dashboard-data-controls")?.hasAttribute("data-overlay-open") &&
        document.querySelector("#dashboard-data-controls-panel")?.hidden
      )
    `,
    2_000,
    "runtime context controls overlay to close"
  )

  await client.send("Runtime.evaluate", {
    expression: `
      (() => {
        document.querySelector("#edit-layout-toggle")?.click()
      })()
    `,
    returnByValue: true,
  })

  await waitForExpression(
    client,
    `
      Boolean(
        document.querySelector("[phx-hook='DashboardGrid']")?.dataset.editMode === "true" &&
        (
          document.querySelector("[phx-hook='DashboardGrid'] .grid-stack-item")?.classList.contains("ui-draggable") ||
          document.querySelector("[phx-hook='DashboardGrid'] .grid-stack-item .ui-resizable-handle")
        )
      )
    `,
    3_000,
    "dashboard grid to enter interactive edit mode"
  )

  const editEnteredResult = await client.send("Runtime.evaluate", {
    expression: `
      (() => {
        const grid = document.querySelector("[phx-hook='DashboardGrid']")
        const firstItem = grid?.querySelector(".grid-stack-item")

        return {
          editing: grid?.dataset.editMode === "true",
          interactive: Boolean(firstItem?.classList.contains("ui-draggable") || firstItem?.querySelector(".ui-resizable-handle"))
        }
      })()
    `,
    returnByValue: true,
  })

  const layoutMutationResult = await client.send("Runtime.evaluate", {
    expression: `
      (() => {
        const gridEl = document.querySelector("[phx-hook='DashboardGrid']")
        const grid = gridEl?.gridstack
        const item = gridEl?.querySelector(".grid-stack-item")
        const node = item?.gridstackNode

        if (!gridEl || !grid || !item || !node) {
          return { ok: false, reason: "gridstack instance unavailable" }
        }

        const before = {
          placementId: item.getAttribute("gs-id") || "",
          x: node.x,
          y: node.y,
          w: node.w,
          h: node.h
        }
        // Edit mode runs float(false): a vertical move into empty space
        // compacts straight back, so mutate height — resizes stick.
        const after = { ...before, h: before.h + 1 }

        grid.update(item, { x: after.x, y: after.y, w: after.w, h: after.h })

        return {
          ok: true,
          before,
          after,
          dom: {
            placementId: item.getAttribute("gs-id") || "",
            x: Number(item.getAttribute("gs-x") || 0),
            y: Number(item.getAttribute("gs-y") || 0),
            w: Number(item.getAttribute("gs-w") || 1),
            h: Number(item.getAttribute("gs-h") || 1)
          }
        }
      })()
    `,
    returnByValue: true,
  })

  assert.equal(layoutMutationResult.result.value.ok, true, "edit layout should expose GridStack instance")
  assert.notEqual(
    layoutMutationResult.result.value.before.placementId,
    "",
    "layout mutation should target a placement"
  )
  assert.equal(
    layoutMutationResult.result.value.dom.placementId,
    layoutMutationResult.result.value.before.placementId,
    "mutated DOM placement should match target placement"
  )
  assert.equal(
    layoutMutationResult.result.value.dom.h,
    layoutMutationResult.result.value.after.h,
    "GridStack update should resize target placement in the DOM"
  )

  await new Promise((resolve) => setTimeout(resolve, 700))

  await client.send("Runtime.evaluate", {
    expression: `
      (() => {
        document.querySelector("#edit-layout-toggle")?.click()
      })()
    `,
    returnByValue: true,
  })

  await waitForExpression(
    client,
    `
      Boolean(
        document.querySelector("[phx-hook='DashboardGrid']")?.dataset.editMode === "false" &&
        !document.querySelector("[phx-hook='DashboardGrid'] .grid-stack-item")?.classList.contains("ui-draggable") &&
        !document.querySelector("[phx-hook='DashboardGrid'] .grid-stack-item .ui-resizable-handle")
      )
    `,
    3_000,
    "dashboard grid to return to static view mode"
  )

  assert.equal(editEnteredResult.result.value.editing, true, "edit layout should enter edit mode")
  assert.equal(editEnteredResult.result.value.interactive, true, "edit layout should arm GridStack interaction handles")

  const preReloadResult = await client.send("Runtime.evaluate", {
    expression: `
      (() => ({
        url: window.location.href,
        panelPresent: Boolean(document.querySelector("#dashboard-panel")),
        selectedDataLinkPresent: Boolean(document.querySelector("#dashboard-data-link-inspector"))
      }))()
    `,
    returnByValue: true,
  })

  assert.equal(preReloadResult.result.value.panelPresent, false, "layout editing should close the selected panel")
  assert.equal(
    preReloadResult.result.value.selectedDataLinkPresent,
    false,
    "layout editing should clear the selected data-link inspector"
  )

  const reloaded = client.once("Page.loadEventFired")
  await client.send("Page.reload", { ignoreCache: true })
  await reloaded
  await waitForDocumentBody(client)
  await waitForProfileReady(client, profile, LIVE_INTERACTION_VIEWPORT)

  const reloadResult = await client.send("Runtime.evaluate", {
    expression: `
      (() => ({
        url: window.location.href,
        dashboardPresent: Boolean(document.querySelector("#ops-dashboard-show-page")),
        panelPresent: Boolean(document.querySelector("#dashboard-panel")),
        selectedDataLinkPresent: Boolean(document.querySelector("#dashboard-data-link-inspector")),
        liveSocketConnected: Boolean(window.liveSocket?.isConnected?.()),
        chartRendered: Boolean(document.querySelector("[phx-hook='TelemetryChart'] .uplot"))
      }))()
    `,
    returnByValue: true,
  })

  assert.equal(
    reloadResult.result.value.url,
    preReloadResult.result.value.url,
    "dashboard reload should preserve the post-edit operational URL"
  )
  assert.equal(reloadResult.result.value.dashboardPresent, true, "dashboard should render after reload")
  assert.equal(reloadResult.result.value.panelPresent, false, "closed panel should remain closed after reload")
  assert.equal(
    reloadResult.result.value.selectedDataLinkPresent,
    false,
    "cleared data-link selection should remain cleared after reload"
  )
  assert.equal(reloadResult.result.value.liveSocketConnected, true, "LiveSocket should reconnect after reload")
  assert.equal(reloadResult.result.value.chartRendered, true, "chart hook should render after reload")

  const contextRailAfterReload = await inspectOpsContextRail(client, {
    expectInitiallyExpanded: true,
    restoreCollapsed: true,
  })

  const limitAnalysisEvidence = await inspectRenderedLimitAnalysisEvidence(client, {
    inspectFrameEvidence: true,
  })

  const persistedLayoutResult = await client.send("Runtime.evaluate", {
    expression: `
      (() => {
        const placementId = ${JSON.stringify(layoutMutationResult.result.value.before.placementId)}
        const item = document.querySelector('[gs-id="' + placementId + '"]')

        return {
          placementId,
          present: Boolean(item),
          x: Number(item?.getAttribute("gs-x") || 0),
          y: Number(item?.getAttribute("gs-y") || 0),
          w: Number(item?.getAttribute("gs-w") || 1),
          h: Number(item?.getAttribute("gs-h") || 1)
        }
      })()
    `,
    returnByValue: true,
  })

  assert.equal(persistedLayoutResult.result.value.present, true, "mutated placement should render after reload")
  assert.equal(
    persistedLayoutResult.result.value.h,
    layoutMutationResult.result.value.after.h,
    "dashboard reload should preserve mutated placement size"
  )

  const workflowSurfaces = await runLiveWorkflowSurfaceInteractions(client)
  const comparisonReview = await runComparisonReviewInteraction(client, profile)

  return {
    viewport: LIVE_INTERACTION_VIEWPORT.name,
    menu: menuResult.result.value,
    context: contextResult.result.value,
    edit: {
      ...editEnteredResult.result.value,
      returnedToView: true,
    },
    layoutMutation: {
      ...layoutMutationResult.result.value,
      persisted: persistedLayoutResult.result.value,
    },
    reload: reloadResult.result.value,
    contextRail: {
      initial: contextRail,
      afterReload: contextRailAfterReload,
    },
    limitAnalysisEvidence,
    workflowSurfaces,
    comparisonReview,
  }
}

async function runRuntimeContextBatchInspection(client, _profile, config) {
  const {
    scopeKind,
    expectedScopeIds,
    searchQuery,
    expectedLabel,
    resultDescription,
  } = config
  const expectedScopeIdsParam = expectedScopeIds.join(",")

  assert.equal(
    expectedScopeIds.length > 1,
    true,
    `runtime context ${resultDescription} batch smoke requires at least two expected ids`
  )

  await loadViewport(client, dashboardUrl(), LIVE_INTERACTION_VIEWPORT)
  await waitForExpression(
    client,
    `
      Boolean(
        window.liveSocket &&
        window.liveSocket.isConnected &&
        window.liveSocket.isConnected() &&
        document.querySelector("#context-search") &&
        document.querySelector("[phx-hook='DashboardGrid'].grid-stack[class*='gs-id-']")
      )
    `,
    10_000,
    `${resultDescription} runtime context selector`
  )

  const searchInputResult = await client.send("Runtime.evaluate", {
    expression: `
      (() => {
        const input = document.querySelector("#context-search")
        if (!input) return { ok: false, reason: "context search input missing" }
        input.focus()
        return { ok: true }
      })()
    `,
    returnByValue: true,
  })

  assert.equal(
    searchInputResult.result.value?.ok,
    true,
    searchInputResult.result.value?.reason || "context search input should focus"
  )

  await client.send("Input.insertText", { text: searchQuery })

  await waitForExpression(
    client,
    `
      (() => {
        const action = document.querySelector("[data-dashboard-context-batch-result='${scopeKind}']")
        return (
          action?.dataset.dashboardContextBatchIds === ${JSON.stringify(expectedScopeIdsParam)} &&
          action?.dataset.dashboardContextBatchCount === ${JSON.stringify(String(expectedScopeIds.length))}
        )
      })()
    `,
    5_000,
    `${resultDescription} context batch result`
  )

  await clickAndWaitForSelector(
    client,
    `[data-dashboard-context-batch-result='${scopeKind}']`,
    `#dashboard-selected-context[data-dashboard-selected-context-kind='${scopeKind}']`,
    `${resultDescription} context batch selection`,
    20_000
  )

  await waitForExpression(
    client,
    `
      (() => {
        const root = document.querySelector("#ops-dashboard-show-page")
        const selected = document.querySelector("#dashboard-selected-context")
        const url = new URL(window.location.href)

        return (
          root?.dataset.dashboardScopeKind === ${JSON.stringify(scopeKind)} &&
          root?.dataset.dashboardScopeId === ${JSON.stringify(expectedScopeIds[0])} &&
          root?.dataset.dashboardScopeIds === ${JSON.stringify(expectedScopeIdsParam)} &&
          selected?.dataset.dashboardSelectedContextKind === ${JSON.stringify(scopeKind)} &&
          selected?.dataset.dashboardSelectedContextId === ${JSON.stringify(expectedScopeIds[0])} &&
          selected?.dataset.dashboardSelectedContextIds === ${JSON.stringify(expectedScopeIdsParam)} &&
          (selected?.textContent || "").includes(${JSON.stringify(expectedLabel)}) &&
          url.searchParams.get("scope_kind") === ${JSON.stringify(scopeKind)} &&
          (url.searchParams.get("scope_id") || "") === "" &&
          url.searchParams.get("scope_ids") === ${JSON.stringify(expectedScopeIdsParam)}
        )
      })()
    `,
    5_000,
    `${resultDescription} context batch route and selected badge`
  )

  const selectedResult = await client.send("Runtime.evaluate", {
    expression: `
      (() => {
        const root = document.querySelector("#ops-dashboard-show-page")
        const selected = document.querySelector("#dashboard-selected-context")
        const url = new URL(window.location.href)

        return {
          rootScopeKind: root?.dataset.dashboardScopeKind || "",
          rootScopeId: root?.dataset.dashboardScopeId || "",
          rootScopeIds: root?.dataset.dashboardScopeIds || "",
          selectedKind: selected?.dataset.dashboardSelectedContextKind || "",
          selectedId: selected?.dataset.dashboardSelectedContextId || "",
          selectedIds: selected?.dataset.dashboardSelectedContextIds || "",
          selectedLabel: selected?.textContent?.replace(/\\s+/g, " ").trim() || "",
          routeScopeKind: url.searchParams.get("scope_kind") || "",
          routeScopeId: url.searchParams.get("scope_id") || "",
          routeScopeIds: url.searchParams.get("scope_ids") || "",
        }
      })()
    `,
    returnByValue: true,
  })

  await clickAndWaitForSelector(
    client,
    "#dashboard-selected-context + button[aria-label='Clear context']",
    "#ops-dashboard-show-page",
    `clear ${resultDescription} context batch selection`
  )

  await waitForExpression(
    client,
    `
      (() => {
        const selected = document.querySelector("#dashboard-selected-context")
        const url = new URL(window.location.href)

        return (
          !selected &&
          !url.searchParams.has("scope_kind") &&
          !url.searchParams.has("scope_id") &&
          !url.searchParams.has("scope_ids")
        )
      })()
    `,
    5_000,
    `${resultDescription} context batch clear route`
  )

  const clearedResult = await client.send("Runtime.evaluate", {
    expression: `
      (() => {
        const selected = document.querySelector("#dashboard-selected-context")
        const url = new URL(window.location.href)

        return {
          selectedPresent: Boolean(selected),
          routeScopeKind: url.searchParams.get("scope_kind") || "",
          routeScopeId: url.searchParams.get("scope_id") || "",
          routeScopeIds: url.searchParams.get("scope_ids") || "",
        }
      })()
    `,
    returnByValue: true,
  })

  return {
    searchQuery,
    expectedScopeIds,
    selected: selectedResult.result.value,
    cleared: clearedResult.result.value,
  }
}

