  assert.equal(initial.rootScopeIds, scopeIdsParam, "dashboard root should preserve full contact scope set")
  assert.equal(initial.alphaLanePresent, true, "alpha contact lane should render")
  assert.equal(initial.betaLanePresent, true, "beta contact lane should render")
  assert.equal(initial.excludedLanePresent, false, "unselected contact lane should be filtered")
  assert.equal(initial.betaRow.observable, "contacts.phase", "beta row should preserve observable")
