async function runSourceEndpointOperationalResourceInspection(client, profile) {
  const sourceEndpointId = expectedSourceEndpointId()
  const transportId = expectedTransportId()
  const expectedOperationalEventId = argValue("--expected-operational-event-id") || ""
  assert.notEqual(sourceEndpointId, "", "source-endpoint operational-resource smoke requires a source endpoint id")
  assert.notEqual(transportId, "", "source-endpoint operational-resource smoke requires a transport id")
  assert.notEqual(
    expectedOperationalEventId,
    "",
    "source-endpoint operational-resource smoke requires an operational event id"
  )

  const rowId = `comms.transport.connection_state:${transportId}`
  const rowSelector = `[data-status-matrix-row='${rowId}']`
  const evidenceSelector = `${rowSelector} [data-status-matrix-row-evidence='${rowId}']`
  const rowLinkSelector = `${rowSelector} [data-status-matrix-row-link='${rowId}'][data-status-matrix-row-link-target='transport']`

  await loadViewport(client, dashboardUrl(), LIVE_INTERACTION_VIEWPORT)
  await waitForExpression(
    client,
    `
      Boolean(
        window.liveSocket &&
        window.liveSocket.isConnected &&
        window.liveSocket.isConnected() &&
        document.querySelector("[phx-hook='DashboardGrid'].grid-stack[class*='gs-id-']") &&
        document.querySelector("#ops-dashboard-show-page")
      )
    `,
    10_000,
    `source-endpoint operational-resource dashboard shell in ${LIVE_INTERACTION_VIEWPORT.name} viewport`
  )

  await waitForExpression(
    client,
    `
      (() => {
        const sourceEndpointId = ${JSON.stringify(sourceEndpointId)}
        const transportId = ${JSON.stringify(transportId)}
        const root = document.querySelector("#ops-dashboard-show-page")
        const row = document.querySelector(${JSON.stringify(rowSelector)})
        const link = document.querySelector(${JSON.stringify(rowLinkSelector)})
        const betaRow = document.querySelector("[data-status-matrix-row='comms.transport.connection_state:browser-transport-beta']")

        return (
          root?.dataset.dashboardScopeKind === "source_endpoint" &&
          root?.dataset.dashboardScopeId === sourceEndpointId &&
          row?.dataset.statusMatrixSource === "operational_observables" &&
          row?.dataset.statusMatrixResourceId === transportId &&
          row?.dataset.statusMatrixSourceEndpointId === sourceEndpointId &&
          link?.getAttribute("phx-value-target-id") === transportId &&
          !betaRow
        )
      })()
    `,
    5_000,
    "source-endpoint scoped operational resource row"
  )

  const initialResult = await client.send("Runtime.evaluate", {
    expression: `
      (() => {
        const row = document.querySelector(${JSON.stringify(rowSelector)})
        const link = document.querySelector(${JSON.stringify(rowLinkSelector)})
        const value = row?.querySelector("[data-status-matrix-field='value']")
        const quality = row?.querySelector("[data-status-matrix-field='quality']")
        const time = row?.querySelector("[data-status-matrix-field='time']")

        return {
          url: window.location.href,
          rootScopeKind: document.querySelector("#ops-dashboard-show-page")?.dataset.dashboardScopeKind || "",
          rootScopeId: document.querySelector("#ops-dashboard-show-page")?.dataset.dashboardScopeId || "",
          rowPresent: Boolean(row),
          betaPresent: Boolean(document.querySelector("[data-status-matrix-row='comms.transport.connection_state:browser-transport-beta']")),
          source: row?.dataset.statusMatrixSource || "",
          statusPolicy: row?.dataset.statusMatrixStatusPolicy || "",
          resourceId: row?.dataset.statusMatrixResourceId || "",
          transportId: row?.dataset.statusMatrixTransportId || "",
          scopeKind: row?.dataset.statusMatrixScopeKind || "",
          sourceEndpointId: row?.dataset.statusMatrixSourceEndpointId || "",
          groundStationId: row?.dataset.statusMatrixGroundStationId || "",
          observableId: row?.dataset.statusMatrixFrameObservableId || "",
          productFamily: row?.dataset.statusMatrixProductFamily || "",
          supportedCapability: row?.dataset.statusMatrixSupportedCapability || "",
          dataSourceId: row?.dataset.statusMatrixDataSourceId || "",
          sourceBindingId: row?.dataset.statusMatrixSourceBindingId || "",
          rowLinkTarget: link?.dataset.statusMatrixRowLinkTarget || "",
          rowLinkId: link?.dataset.statusMatrixRowLinkId || "",
          phxTarget: link?.getAttribute("phx-value-target") || "",
          phxTargetId: link?.getAttribute("phx-value-target-id") || "",
          phxDataSourceId: link?.getAttribute("phx-value-data-source-id") || "",
          phxSourceBindingId: link?.getAttribute("phx-value-source-binding-id") || "",
          valueText: value?.textContent?.replace(/\\s+/g, " ").trim() || "",
          qualityText: quality?.textContent?.replace(/\\s+/g, " ").trim() || "",
          timeText: time?.textContent?.replace(/\\s+/g, " ").trim() || ""
        }
      })()
    `,
    returnByValue: true,
  })

  const initial = initialResult.result.value
  assert.equal(initial.rootScopeKind, "source_endpoint", "dashboard root should render source-endpoint scope")
  assert.equal(initial.rootScopeId, sourceEndpointId, "dashboard root should preserve source endpoint id")
  assert.equal(initial.rowPresent, true, "operational resource row should render")
  assert.equal(initial.betaPresent, false, "source-endpoint scope should filter out the beta transport")
  assert.equal(initial.source, "operational_observables", "row should come from operational observables")
  assert.equal(initial.statusPolicy, "connection_state", "row should preserve connection-state policy")
  assert.equal(initial.resourceId, transportId, "row should identify the transport resource")
  assert.equal(initial.transportId, transportId, "row should carry transport id")
  assert.equal(initial.scopeKind, "transport", "row scope should identify transport resource scope")
  assert.equal(initial.sourceEndpointId, sourceEndpointId, "row should preserve source endpoint id")
  assert.equal(initial.groundStationId, "dss-14", "row should preserve ground station context")
  assert.equal(
    initial.observableId,
    "comms.transport.connection_state",
    "row should preserve frame observable id"
  )
  assert.equal(initial.productFamily, "connection_state", "row should preserve product family")
  assert.equal(initial.supportedCapability, "connection_state", "row should preserve capability")
  assert.equal(initial.dataSourceId, "managed_operational_observables", "row should preserve data source")
  assert.equal(
    initial.sourceBindingId,
    "default_flight_operational_observables",
    "row should preserve source binding"
  )
  assert.equal(initial.rowLinkTarget, "transport", "row link should target transport")
  assert.equal(initial.rowLinkId, transportId, "row link should target the selected transport id")
  assert.equal(initial.phxTarget, "transport", "row link event should target transport")
  assert.equal(initial.phxTargetId, transportId, "row link event should carry transport id")
  assert.equal(
    initial.phxDataSourceId,
    "managed_operational_observables",
    "row link should carry data source id"
  )
  assert.equal(
    initial.phxSourceBindingId,
    "default_flight_operational_observables",
    "row link should carry source binding id"
  )
  assert.match(initial.valueText, /Connected/, "connection state should render canonical latest state")
  assert.match(initial.qualityText, /Tcp socket/i, "connection state row should identify TCP socket quality")
  assert.match(initial.timeText, new RegExp(transportId), "connection state row should include transport id")

  await clickAndWaitForSelector(
    client,
    rowLinkSelector,
    "#dashboard-data-link-inspector[data-data-link-target='transport'][data-data-link-status='resolved']",
    "source-endpoint operational resource transport data link"
  )

  const dataLinkResult = await client.send("Runtime.evaluate", {
    expression: `
      (() => {
        const transportId = ${JSON.stringify(transportId)}
        const sourceEndpointId = ${JSON.stringify(sourceEndpointId)}
        const inspector = document.querySelector("#dashboard-data-link-inspector")
        const copy = document.querySelector("#dashboard-data-link-copy-link")
        const url = new URL(window.location.href)
        const fieldText = (label) => (
          Array.from(inspector?.querySelectorAll("[data-data-link-field]") || [])
            .find((field) => field.dataset.dataLinkField === label)
            ?.textContent?.replace(/\\s+/g, " ").trim() || ""
        )
        const contextText = (label) => (
          Array.from(inspector?.querySelectorAll("[data-data-link-context]") || [])
            .find((field) => field.dataset.dataLinkContext === label)
            ?.textContent?.replace(/\\s+/g, " ").trim() || ""
        )

        return {
          present: Boolean(inspector),
          target: inspector?.dataset.dataLinkTarget || "",
          status: inspector?.dataset.dataLinkStatus || "",
          selectedTarget: url.searchParams.get("selected_target") || "",
          selectedId: url.searchParams.get("selected_id") || "",
          scopeKind: url.searchParams.get("scope_kind") || "",
          scopeId: url.searchParams.get("scope_id") || "",
          realm: url.searchParams.get("realm") || "",
          replayRunId: url.searchParams.get("replay_run_id") || "",
          dataSourceId: url.searchParams.get("data_source_id") || "",
          sourceBindingId: url.searchParams.get("source_binding_id") || "",
          displayName: fieldText("Display name"),
          dataSourceContext: contextText("Data source"),
          sourceBindingContext: contextText("Source binding"),
          copyText: copy?.dataset.clipboardText || "",
          copyHook: copy?.getAttribute("phx-hook") || ""
        }
      })()
    `,
    returnByValue: true,
  })

  const dataLink = dataLinkResult.result.value
  assert.equal(dataLink.present, true, "transport DataLink inspector should render")
  assert.equal(dataLink.target, "transport", "DataLink inspector should target transport")
  assert.equal(dataLink.status, "resolved", "transport DataLink should resolve")
  assert.equal(dataLink.selectedTarget, "transport", "route should select transport")
  assert.equal(dataLink.selectedId, transportId, "route should select the transport id")
  assert.equal(dataLink.scopeKind, "source_endpoint", "route should preserve source-endpoint scope")
  assert.equal(dataLink.scopeId, sourceEndpointId, "route should preserve source endpoint id")
  assert.equal(dataLink.realm, "flight", "route should preserve flight realm")
  assert.equal(
    dataLink.dataSourceId,
    "managed_operational_observables",
    "route should preserve operational data source"
  )
  assert.equal(
    dataLink.sourceBindingId,
    "default_flight_operational_observables",
    "route should preserve operational source binding"
  )
  assert.match(dataLink.displayName, /Alpha TCP/, "transport DataLink should resolve setup display name")
  assert.match(
    dataLink.dataSourceContext,
    /managed_operational_observables/,
    "DataLink inspector should show data source context"
  )
  assert.match(
    dataLink.sourceBindingContext,
    /default_flight_operational_observables/,
    "DataLink inspector should show source binding context"
  )
  assert.equal(dataLink.copyHook, "ClipboardButton", "DataLink copy action should use ClipboardButton")
  assert.match(
    dataLink.copyText,
    new RegExp(`scope_kind=source_endpoint`),
    "copy payload should preserve source-endpoint scope kind"
  )
  assert.match(
    dataLink.copyText,
    new RegExp(`scope_id=${sourceEndpointId}`),
    "copy payload should preserve source endpoint id"
  )
  assert.match(
    dataLink.copyText,
    new RegExp(`selected_target=transport`),
    "copy payload should preserve selected target"
  )
  assert.match(
    dataLink.copyText,
    new RegExp(`selected_id=${transportId}`),
    "copy payload should preserve selected transport"
  )
  assert.match(
    dataLink.copyText,
    new RegExp(`data_source_id=managed_operational_observables`),
    "copy payload should preserve operational data source"
  )
  assert.match(
    dataLink.copyText,
    new RegExp(`source_binding_id=default_flight_operational_observables`),
    "copy payload should preserve operational source binding"
  )

  const evidence = await inspectLatestOperationalStateRowEvidence(client, {
    evidenceSelector,
    intervalTarget: "transport_connection_state_interval",
    intervalIdPattern: /^effective_interval:transport_connection_state:/,
    expectedOperationalEventId,
    expectedSubjectPattern: /connection_state|comms\.transport\.connection_state/,
    expectedBodyPattern: /transport_connection_state|browser-transport-alpha|Connected/i,
    expectedObservable: "comms.transport.connection_state",
    expectedScopeKind: "source_endpoint",
    expectedScopeId: sourceEndpointId,
    description: "source-endpoint connection latest",
  })

  return {
    sourceEndpointId,
    transportId,
    initial,
    dataLink,
    evidence,
  }
}

async function runOperationalCommandQueueDepthInspection(client, profile) {
  const {
    missionId,
    sourceEndpointId,
    resourceScopeKind,
    resourceId,
    rootScopeId,
    routeScopeId,
    expectedScopeIds,
    expectedScopeIdsParam,
    expectedEvidenceScopeIds,
    resourceLinkExpected,
  } = commandQueueScopeConfig()
  const resourceLinkTargetText = resourceScopeKind.replaceAll("_", " ")
  const expectedDepth = expectedCommandQueueDepth()
  assert.notEqual(resourceId, "", "operational command-queue smoke requires a scoped resource id")
  assert.equal(expectedScopeIds.length > 0, true, "operational command-queue smoke requires scope ids")

  const rowId = `commanding.queue_depth:${resourceId}`
  const rowSelector = `[data-status-matrix-row='${rowId}']`
  const evidenceSelector = `${rowSelector} [data-status-matrix-row-evidence='${rowId}']`
  const rowLinkSelector = `${rowSelector} [data-status-matrix-row-link-target='${resourceLinkTargetText}'][data-status-matrix-row-link-id='${resourceId}']`

  await loadViewport(client, dashboardUrl(), LIVE_INTERACTION_VIEWPORT)
  await waitForExpression(
    client,
    `
      Boolean(
        window.liveSocket &&
        window.liveSocket.isConnected &&
        window.liveSocket.isConnected() &&
        document.querySelector("[phx-hook='DashboardGrid'].grid-stack[class*='gs-id-']") &&
        document.querySelector("#ops-dashboard-show-page")
      )
    `,
    10_000,
    `operational command-queue dashboard shell in ${LIVE_INTERACTION_VIEWPORT.name} viewport`
  )

  await waitForExpression(
    client,
    `
      (() => {
        const resourceId = ${JSON.stringify(resourceId)}
        const resourceScopeKind = ${JSON.stringify(resourceScopeKind)}
        const expectedDepth = ${JSON.stringify(expectedDepth)}
        const root = document.querySelector("#ops-dashboard-show-page")
        const row = document.querySelector(${JSON.stringify(rowSelector)})
        const evidence = document.querySelector(${JSON.stringify(evidenceSelector)})
        const value = row?.querySelector("[data-status-matrix-field='value']")

        return (
          root?.dataset.dashboardScopeKind === resourceScopeKind &&
          root?.dataset.dashboardScopeId === ${JSON.stringify(rootScopeId)} &&
          root?.dataset.dashboardScopeIds === ${JSON.stringify(expectedScopeIdsParam)} &&
          row?.dataset.statusMatrixSource === "operational_observables" &&
          row?.dataset.statusMatrixResourceId === resourceId &&
          row?.dataset.statusMatrixScopeKind === resourceScopeKind &&
          row?.dataset.statusMatrixQueryScopeKind === resourceScopeKind &&
          row?.dataset.statusMatrixQueryScopeId === ${JSON.stringify(rootScopeId)} &&
          row?.dataset.statusMatrixQueryScopeIds === ${JSON.stringify(expectedScopeIdsParam)} &&
          row?.dataset.statusMatrixFrameObservableId === "commanding.queue_depth" &&
          row?.dataset.statusMatrixProductFamily === "commanding" &&
          row?.dataset.statusMatrixSupportedCapability === "command_queue_depth" &&
          row?.dataset.statusMatrixDataSourceId === "managed_operational_observables" &&
          row?.dataset.statusMatrixSourceBindingId === "default_flight_operational_observables" &&
          value?.textContent?.match(new RegExp("\\\\b" + expectedDepth + "\\\\b")) &&
          evidence?.getAttribute("phx-value-logical-source") === "operational_observables" &&
          evidence?.getAttribute("phx-value-data-source-id") === "managed_operational_observables" &&
          evidence?.getAttribute("phx-value-source-binding-id") === "default_flight_operational_observables" &&
          evidence?.getAttribute("phx-value-scope-kind") === resourceScopeKind &&
          evidence?.getAttribute("phx-value-scope-id") === ${JSON.stringify(rootScopeId)} &&
          (evidence?.getAttribute("phx-value-scope-ids") || "") === ${JSON.stringify(expectedEvidenceScopeIds)}
        )
      })()
    `,
    5_000,
    `${resourceScopeKind}-scoped operational command queue depth row`
  )

  const initialResult = await client.send("Runtime.evaluate", {
    expression: `
      (() => {
        const row = document.querySelector(${JSON.stringify(rowSelector)})
        const evidence = document.querySelector(${JSON.stringify(evidenceSelector)})
        const link = row?.querySelector("[data-status-matrix-row-link]")
        const scopedLink = row?.querySelector(${JSON.stringify(rowLinkSelector)})
        const observable = row?.querySelector("[data-status-matrix-field='observable']")
        const value = row?.querySelector("[data-status-matrix-field='value']")
        const quality = row?.querySelector("[data-status-matrix-field='quality']")
        const time = row?.querySelector("[data-status-matrix-field='time']")

        return {
          url: window.location.href,
          rootScopeKind: document.querySelector("#ops-dashboard-show-page")?.dataset.dashboardScopeKind || "",
          rootScopeId: document.querySelector("#ops-dashboard-show-page")?.dataset.dashboardScopeId || "",
          rowPresent: Boolean(row),
          source: row?.dataset.statusMatrixSource || "",
          statusPolicy: row?.dataset.statusMatrixStatusPolicy || "",
          resourceId: row?.dataset.statusMatrixResourceId || "",
          scopeKind: row?.dataset.statusMatrixScopeKind || "",
          queryScopeKind: row?.dataset.statusMatrixQueryScopeKind || "",
          queryScopeId: row?.dataset.statusMatrixQueryScopeId || "",
          queryScopeIds: row?.dataset.statusMatrixQueryScopeIds || "",
          observableId: row?.dataset.statusMatrixFrameObservableId || "",
          productFamily: row?.dataset.statusMatrixProductFamily || "",
          supportedCapability: row?.dataset.statusMatrixSupportedCapability || "",
          dataSourceId: row?.dataset.statusMatrixDataSourceId || "",
          sourceBindingId: row?.dataset.statusMatrixSourceBindingId || "",
          rowLinkPresent: Boolean(link),
          scopedLinkPresent: Boolean(scopedLink),
          scopedLinkTarget: scopedLink?.dataset.statusMatrixRowLinkTarget || "",
          scopedLinkId: scopedLink?.dataset.statusMatrixRowLinkId || "",
          evidenceObservable: evidence?.dataset.statusMatrixRowEvidenceObservable || "",
          evidenceKind: evidence?.getAttribute("phx-value-kind") || "",
          evidencePlacement: evidence?.getAttribute("phx-value-placement-id") || "",
          evidenceSourceRequest: evidence?.getAttribute("phx-value-source-request-id") || "",
          evidenceLogicalSource: evidence?.getAttribute("phx-value-logical-source") || "",
          evidenceRealm: evidence?.getAttribute("phx-value-realm") || "",
          evidenceDataSourceId: evidence?.getAttribute("phx-value-data-source-id") || "",
          evidenceSourceBindingId: evidence?.getAttribute("phx-value-source-binding-id") || "",
          evidenceScopeKind: evidence?.getAttribute("phx-value-scope-kind") || "",
          evidenceScopeId: evidence?.getAttribute("phx-value-scope-id") || "",
          evidenceScopeIds: evidence?.getAttribute("phx-value-scope-ids") || "",
          observableText: observable?.textContent?.replace(/\\s+/g, " ").trim() || "",
          valueText: value?.textContent?.replace(/\\s+/g, " ").trim() || "",
          qualityText: quality?.textContent?.replace(/\\s+/g, " ").trim() || "",
          timeText: time?.textContent?.replace(/\\s+/g, " ").trim() || ""
        }
      })()
    `,
    returnByValue: true,
  })

  const initial = initialResult.result.value
  assert.equal(initial.rootScopeKind, resourceScopeKind, "dashboard root should render requested scope")
  assert.equal(initial.rootScopeId, rootScopeId, "dashboard root should preserve scoped resource id")
  assert.equal(initial.rowPresent, true, "command queue depth row should render")
  assert.equal(initial.source, "operational_observables", "row should come from operational observables")
  assert.equal(initial.statusPolicy, "metric_value", "row should preserve metric-value policy")
  assert.equal(initial.resourceId, resourceId, "row should identify the scoped command queue resource")
  assert.equal(initial.scopeKind, resourceScopeKind, "row scope should identify requested command queue scope")
  assert.equal(initial.queryScopeKind, resourceScopeKind, "row query scope should preserve dashboard scope kind")
  assert.equal(initial.queryScopeId, rootScopeId, "row query scope should preserve dashboard scope id")
  assert.equal(initial.queryScopeIds, expectedScopeIdsParam, "row query scope should expose the dashboard scope id set")
  assert.equal(initial.observableId, "commanding.queue_depth", "row should preserve frame observable id")
  assert.equal(initial.productFamily, "commanding", "row should preserve product family")
  assert.equal(initial.supportedCapability, "command_queue_depth", "row should preserve capability")
  assert.equal(initial.dataSourceId, "managed_operational_observables", "row should preserve data source")
  assert.equal(
    initial.sourceBindingId,
    "default_flight_operational_observables",
    "row should preserve source binding"
  )
  if (!resourceLinkExpected) {
    assert.equal(initial.rowLinkPresent, false, "aggregate command queue row should not invent a resource DataLink")
  } else {
    assert.equal(initial.scopedLinkPresent, true, "scoped command queue row should expose a resource DataLink")
    assert.equal(
      initial.scopedLinkTarget,
      resourceLinkTargetText,
      "scoped command queue DataLink should preserve target kind"
    )
    assert.equal(
      initial.scopedLinkId,
      resourceId,
      "scoped command queue DataLink should preserve target id"
    )
  }
  assert.equal(initial.evidenceObservable, "commanding.queue_depth", "row evidence should preserve observable")
  assert.equal(initial.evidenceKind, "frame", "row evidence should select frame evidence")
  assert.notEqual(initial.evidencePlacement, "", "row evidence should preserve placement id")
  assert.notEqual(initial.evidenceSourceRequest, "", "row evidence should preserve source request id")
  assert.equal(
    initial.evidenceLogicalSource,
    "operational_observables",
    "row evidence should preserve logical source"
  )
  assert.equal(initial.evidenceRealm, "flight", "row evidence should preserve flight realm")
  assert.equal(
    initial.evidenceDataSourceId,
    "managed_operational_observables",
    "row evidence should preserve data source id"
  )
  assert.equal(
    initial.evidenceSourceBindingId,
    "default_flight_operational_observables",
    "row evidence should preserve source binding id"
  )
  assert.equal(initial.evidenceScopeKind, resourceScopeKind, "row evidence should preserve query scope kind")
  assert.equal(initial.evidenceScopeId, rootScopeId, "row evidence should preserve query scope id")
  assert.equal(
    initial.evidenceScopeIds,
    expectedEvidenceScopeIds,
    "row evidence should preserve multi-scope query ids only when present"
  )
  if (resourceScopeKind === "mission") {
    assert.match(initial.observableText, /Pending commands/, "row should label the queue depth")
  } else {
    assert.match(initial.observableText, new RegExp(resourceId), "row should label the scoped queue depth")
  }
  assert.match(
    initial.valueText,
    new RegExp(`\\b${expectedDepth}\\b`),
    "row should count only pending queue entries in scope"
  )
  assert.match(initial.qualityText, /commands/i, "row should render queue-depth units")
  assert.notEqual(initial.timeText, "", "row should render the aggregate observation time")

  let dataLink = null
  if (resourceLinkExpected) {
    await clickAndWaitForSelector(
      client,
      rowLinkSelector,
      `#dashboard-data-link-inspector[data-data-link-target='${resourceScopeKind}'][data-data-link-status='resolved']`,
      "scoped operational command queue resource DataLink"
    )

    const dataLinkResult = await client.send("Runtime.evaluate", {
      expression: `
        (() => {
          const inspector = document.querySelector("#dashboard-data-link-inspector")
          const copy = document.querySelector("#dashboard-data-link-copy-link")
          const url = new URL(window.location.href)
          if (copy) copy.click()

          return {
            present: Boolean(inspector),
            target: inspector?.dataset.dataLinkTarget || "",
            targetId: inspector?.dataset.dataLinkTargetId || "",
            status: inspector?.dataset.dataLinkStatus || "",
            selectedTarget: url.searchParams.get("selected_target") || "",
            selectedId: url.searchParams.get("selected_id") || "",
            scopeKind: url.searchParams.get("scope_kind") || "",
            scopeId: url.searchParams.get("scope_id") || "",
            dataSourceId: url.searchParams.get("data_source_id") || "",
            sourceBindingId: url.searchParams.get("source_binding_id") || "",
            copyText: copy?.dataset.clipboardText || "",
            copyHook: copy?.getAttribute("phx-hook") || "",
          }
        })()
      `,
      returnByValue: true,
    })

    dataLink = dataLinkResult.result.value
    assert.equal(dataLink.present, true, "scoped command queue DataLink inspector should render")
    assert.equal(dataLink.target, resourceScopeKind, "DataLink inspector should target scoped resource")
    assert.equal(dataLink.targetId, resourceId, "DataLink inspector should resolve scoped resource id")
    assert.equal(dataLink.status, "resolved", "scoped command queue DataLink should resolve")
    assert.equal(dataLink.selectedTarget, resourceScopeKind, "route should select scoped resource target")
    assert.equal(dataLink.selectedId, resourceId, "route should select scoped resource id")
    assert.equal(dataLink.scopeKind, resourceScopeKind, "route should preserve command queue scope kind")
    assert.equal(dataLink.scopeId, routeScopeId, "route should preserve command queue scope id")
    assert.equal(
      dataLink.dataSourceId,
      "managed_operational_observables",
      "route should preserve operational data source"
    )
    assert.equal(
      dataLink.sourceBindingId,
      "default_flight_operational_observables",
      "route should preserve operational source binding"
    )
    assert.equal(dataLink.copyHook, "ClipboardButton", "DataLink copy action should use ClipboardButton")
    assert.match(
      dataLink.copyText,
      new RegExp(`selected_target=${resourceScopeKind}`),
      "copy payload should preserve selected target"
    )
    assert.match(
      dataLink.copyText,
      new RegExp(`selected_id=${resourceId}`),
      "copy payload should preserve selected resource"
    )
  }

  await clickAndWaitForSelector(
    client,
    evidenceSelector,
    "#dashboard-evidence-inspector[data-evidence-kind='frame'][data-evidence-status='resolved']",
    "operational command queue depth frame evidence"
  )

  const evidenceResult = await client.send("Runtime.evaluate", {
    expression: `
      (() => {
        const resourceId = ${JSON.stringify(resourceId)}
        const resourceScopeKind = ${JSON.stringify(resourceScopeKind)}
        const inspector = document.querySelector("#dashboard-evidence-inspector")
        const copy = document.querySelector("#dashboard-evidence-copy-link")
        const url = new URL(window.location.href)
        const detailText = (label) => (
          Array.from(inspector?.querySelectorAll("[data-evidence-detail]") || [])
            .find((field) => field.dataset.evidenceDetail === label)
            ?.textContent?.replace(/\\s+/g, " ").trim() || ""
        )

        return {
          present: Boolean(inspector),
          kind: inspector?.dataset.evidenceKind || "",
          status: inspector?.dataset.evidenceStatus || "",
          subject: inspector?.dataset.evidenceSubject || "",
          selectedEvidenceKind: url.searchParams.get("selected_evidence_kind") || "",
          selectedLogicalSource: url.searchParams.get("selected_logical_source") || "",
          selectedDataSource: url.searchParams.get("selected_data_source") || "",
          selectedSourceBinding: url.searchParams.get("selected_source_binding") || "",
          selectedScopeKind: url.searchParams.get("selected_scope_kind") || "",
          selectedScopeId: url.searchParams.get("selected_scope_id") || "",
          selectedScopeIds: url.searchParams.get("selected_scope_ids") || "",
          scopeKind: url.searchParams.get("scope_kind") || "",
          scopeId: url.searchParams.get("scope_id") || "",
          scopeIds: url.searchParams.get("scope_ids") || "",
          frame: detailText("Frame"),
          logicalSource: detailText("Logical source"),
          dataSource: detailText("Data source"),
          sourceBinding: detailText("Source binding"),
          copyText: copy?.dataset.clipboardText || "",
          copyHook: copy?.getAttribute("phx-hook") || "",
          detailHasResource: Boolean(document.body.textContent.includes(resourceId))
        }
      })()
    `,
    returnByValue: true,
  })

  const evidence = evidenceResult.result.value
  assert.equal(evidence.present, true, "frame evidence inspector should render")
  assert.equal(evidence.kind, "frame", "evidence inspector should preserve frame kind")
  assert.equal(evidence.status, "resolved", "frame evidence should resolve")
  assert.match(evidence.subject, /command_queue_depth/, "frame evidence should identify the command queue frame")
  assert.equal(evidence.selectedEvidenceKind, "frame", "route should select frame evidence")
  assert.equal(evidence.selectedLogicalSource, "operational_observables", "route should preserve logical source")
  assert.equal(evidence.selectedDataSource, "managed_operational_observables", "route should preserve data source")
  assert.equal(
    evidence.selectedSourceBinding,
    "default_flight_operational_observables",
    "route should preserve source binding"
  )
  assert.equal(evidence.scopeKind, resourceScopeKind, "route should preserve command queue scope kind")
  assert.equal(evidence.scopeId, routeScopeId, "route should preserve command queue scope id")
  assert.equal(evidence.scopeIds, expectedEvidenceScopeIds, "route should preserve command queue scope ids")
  assert.equal(
    evidence.selectedScopeKind,
    resourceScopeKind,
    "selected evidence params should preserve query scope kind"
  )
  assert.equal(evidence.selectedScopeId, rootScopeId, "selected evidence params should preserve query scope id")
  assert.equal(
    evidence.selectedScopeIds,
    expectedEvidenceScopeIds,
    "selected evidence params should preserve multi-scope ids only when present"
  )
  assert.match(evidence.frame, /command_queue_depth/, "frame evidence should identify command queue frame")
  assert.match(
    evidence.logicalSource,
    /operational_observables/,
    "frame evidence should show logical source"
  )
  assert.match(
    evidence.dataSource,
    /managed_operational_observables/,
    "frame evidence should show data source"
  )
  assert.match(
    evidence.sourceBinding,
    /default_flight_operational_observables/,
    "frame evidence should show source binding"
  )
  assert.equal(evidence.copyHook, "ClipboardButton", "evidence copy action should use ClipboardButton")
  assert.match(
    evidence.copyText,
    /selected_evidence_kind=frame/,
    "copy payload should preserve frame evidence selection"
  )
  assert.match(
    evidence.copyText,
    /selected_logical_source=operational_observables/,
    "copy payload should preserve logical source"
  )
  assert.match(
    evidence.copyText,
    /selected_data_source=managed_operational_observables/,
    "copy payload should preserve data source"
  )
  assert.match(
    evidence.copyText,
    /selected_source_binding=default_flight_operational_observables/,
    "copy payload should preserve source binding"
  )
  assert.match(
    evidence.copyText,
    new RegExp(`scope_kind=${resourceScopeKind}`),
    "copy payload should preserve command queue scope kind"
  )
  if (routeScopeId === "") {
    assert.doesNotMatch(evidence.copyText, /[?&]scope_id=/, "copy payload should not invent a single scope id")
    assert.match(
      evidence.copyText,
      new RegExp(`scope_ids=${encodeURIComponent(expectedScopeIdsParam)}`),
      "copy payload should preserve command queue scope ids"
    )
  } else {
    assert.match(
      evidence.copyText,
      new RegExp(`scope_id=${routeScopeId}`),
      "copy payload should preserve command queue scope id"
    )
  }
  assert.match(
    evidence.copyText,
    new RegExp(`selected_scope_kind=${resourceScopeKind}`),
    "copy payload should preserve selected evidence scope kind"
  )
  assert.match(
    evidence.copyText,
    new RegExp(`selected_scope_id=${rootScopeId}`),
    "copy payload should preserve selected evidence scope id"
  )
  if (expectedEvidenceScopeIds !== "") {
    assert.match(
      evidence.copyText,
      new RegExp(`selected_scope_ids=${encodeURIComponent(expectedEvidenceScopeIds)}`),
      "copy payload should preserve selected evidence scope ids"
    )
  }

  return {
    missionId,
    sourceEndpointId,
    resourceScopeKind,
    resourceId,
    initial,
    dataLink,
    evidence,
  }
}

