  assert.notEqual(expectedOperationalEventId, "", "link operational-resource smoke requires an RF lock event id")
  assert.notEqual(
    expectedFrameSyncOperationalEventId,
    "",
    "link operational-resource smoke requires a frame sync event id"
  )

  const rowSelector = `[data-status-matrix-frame-observable-id='link.rf_lock_state'][data-status-matrix-link-id='${linkId}']`
  const frameSyncRowSelector = `[data-status-matrix-frame-observable-id='link.frame_sync_state'][data-status-matrix-link-id='${linkId}']`
