	          betaLockTableLinkId: betaLockTableRow?.dataset.dataTableLinkId || "",
	          betaLockTableQueryScopeKind: betaLockTableRow?.dataset.dataTableQueryScopeKind || "",
	          betaLockTableQueryScopeId: betaLockTableRow?.dataset.dataTableQueryScopeId || "",
	          betaLockTableQueryScopeIds: betaLockTableRow?.dataset.dataTableQueryScopeIds || "",
	          betaLockTableValueText: betaLockTableValue?.textContent?.replace(/\\s+/g, " ").trim() || "",
