          completeFormStage:
            completeForm?.dataset.historicalWorkflowGroupRecoveryCompleteStage || "",
          completeFormEligible:
            completeForm?.dataset.historicalWorkflowGroupRecoveryCompleteEligible || "",
          completeFormCount:
            completeForm?.dataset.historicalWorkflowGroupRecoveryCompleteCount || "",
          completeFormReason:
            completeForm?.dataset.historicalWorkflowGroupRecoveryCompleteReason || "",
          completeFormPreview:
            completeForm?.dataset.historicalWorkflowGroupRecoveryCompletePreview || "",
          completePresent: Boolean(complete),
          completeStage: complete?.dataset.workflowActionStage || "",
          completeEligible: complete?.dataset.workflowActionEligible || "",
          completeEligibleCount: complete?.dataset.workflowActionEligibleCount || "",
          completeActionId: complete?.dataset.workflowActionId || "",
