        latestJobId: document.querySelector("#dashboard-historical-workflow-latest-action")?.dataset.workflowLatestActionJobId || "",
        latestTargetEventId: document.querySelector("#dashboard-historical-workflow-latest-action")?.dataset.workflowLatestActionTargetEventId || "",
        latestTargetRunId: document.querySelector("#dashboard-historical-workflow-latest-action")?.dataset.workflowLatestActionTargetRunId || "",
