async function runDefaultDashboardScenario(client, url, profile) {
  const results = []

  for (const viewport of DEFAULT_VIEWPORTS) {
    await loadViewport(client, url, viewport)
    await waitForProfileReady(client, profile, viewport)
    const result = await evaluateViewport(client, viewport, profile)
    assertViewport(result)
    results.push(result)
  }

  const interactions = await runLiveDashboardInteractions(client, url, profile)

  return {
    url,
    profile: profile.name,
    results,
    interactions,
  }
}

async function runWorkflowScenario(client, url, profile, mode, scenario) {
  const workflowResult = await scenario.run(client, profile)

  return {
    url,
    profile: profile.name,
    mode,
    [scenario.resultKey]: workflowResult,
  }
}

async function runBrowserScenario(client, url, profile, mode) {
  const workflowScenario = INTERACTION_SCENARIOS[mode]

  if (workflowScenario) {
    return runWorkflowScenario(client, url, profile, mode, workflowScenario)
  }

  assert.equal(
    mode,
    "full",
    `unsupported interaction mode ${mode}; expected full, ${Object.keys(INTERACTION_SCENARIOS).join(", ")}`
  )

  return runDefaultDashboardScenario(client, url, profile)
}

const url = dashboardUrl()
const profile = viewportProfile(profileName())
const credentials = loginCredentials()
const mode = interactionMode()
const timeoutMs = scenarioTimeoutMs()
const runtime = await launchChrome()
const shutdown = installShutdownGuards(runtime)
const pageWsUrl = await createPage(httpBaseFromWebSocket(runtime.devtoolsUrl), credentials ? "about:blank" : url)
const client = new CdpClient(pageWsUrl)

try {
  await client.send("Page.enable")
  await client.send("Runtime.enable")
  client.on("Page.javascriptDialogOpening", () => {
    client.send("Page.handleJavaScriptDialog", { accept: true }).catch(() => {})
  })

  if (credentials) {
    await submitSignIn(client, credentials)
    await selectOrganization(client, argValue("--organization-id"))
  }

  const scenarioResult = await withTimeout(
    runBrowserScenario(client, url, profile, mode),
    timeoutMs,
    `dashboard viewport smoke ${mode}`
  )
  console.log(JSON.stringify(scenarioResult, null, 2))
  console.log("dashboard_viewport_smoke passed")
} finally {
  client.close()
  await shutdown.close()
}
